import XCTest
@testable import Story

// Evidence frame selection policy v2 — Swift/Python parity. Replays every case in
// packages/evidence_mapper/fixtures/parity_v2.json (generated by the Python reference) through the Swift port and
// requires IDENTICAL priority order, adaptive frame count, selections at several payload tiers, and coverage.
// The fixture is read from the repository checkout, so this runs in the iOS Simulator (host file system); on a
// physical device the file is not reachable and the test is skipped (the Simulator run is the gate).
final class EvidenceSelectionParityTests: XCTestCase {

    private struct Fixture: Decodable {
        let policy_version: String
        let max_frames: Int
        let min_frames: Int
        let cases: [Case]
    }
    private struct Interval: Decodable { let start: Double; let end: Double?; let peak: Double?; let confidence: Double? }
    private struct Expected: Decodable {
        let ordered: [Int]; let budget: Int; let core_count: Int; let context_count: Int; let uniform: Bool
        let select: [String: [Int]]; let coverage: [String: [Int]]
    }
    private struct Case: Decodable {
        let name: String
        let sampled_frame_ms: [Int]
        let events: [Interval]; let visual: [Interval]; let narrative: [Interval]
        let expected: [String: Expected]
    }

    private func loadFixture() throws -> Fixture {
        var url = URL(fileURLWithPath: #filePath)
        for _ in 0..<5 { url.deleteLastPathComponent() }          // StoryTests/ -> Story/ -> ios/ -> apps/ -> repo
        let path = url.appendingPathComponent("packages/evidence_mapper/fixtures/parity_v2.json")
        guard FileManager.default.fileExists(atPath: path.path) else {
            throw XCTSkip("parity fixture not reachable from this runner (\(path.path))")
        }
        return try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: path))
    }

    private func cands(_ xs: [Interval]) -> [EvidenceCandidate] {
        xs.map { EvidenceCandidate(start: $0.start, end: $0.end ?? $0.start, peak: $0.peak, confidence: $0.confidence) }
    }

    func test_policy_constants_match_the_reference() throws {
        let f = try loadFixture()
        XCTAssertEqual(f.policy_version, EvidenceFrameMapper.policyVersion)
        XCTAssertEqual(f.max_frames, EvidenceFrameMapper.maxFrames)
        XCTAssertEqual(f.min_frames, EvidenceFrameMapper.minFrames)
    }

    func test_every_fixture_case_matches_the_python_reference_exactly() throws {
        let f = try loadFixture()
        XCTAssertGreaterThanOrEqual(f.cases.count, 12)
        for c in f.cases {
            for (key, vt) in [("highlights", EvidenceVideoType.highlights), ("full_story", .fullStory)] {
                guard let exp = c.expected[key] else { return XCTFail("\(c.name): missing \(key)") }
                let ev = cands(c.events), vi = cands(c.visual), na = cands(c.narrative)
                let r = EvidenceFrameMapper.rank(videoType: vt, sampledFrameMs: c.sampled_frame_ms,
                                                 events: ev, visual: vi, narrative: na)
                let tag = "\(c.name)/\(key)"
                XCTAssertEqual(r.ordered, exp.ordered, "\(tag) priority order")
                XCTAssertEqual(r.budget, exp.budget, "\(tag) adaptive budget")
                XCTAssertEqual(r.coreCount, exp.core_count, "\(tag) core count")
                XCTAssertEqual(r.contextCount, exp.context_count, "\(tag) context count")
                XCTAssertEqual(r.uniform, exp.uniform, "\(tag) uniform")
                for (k, sel) in exp.select {
                    XCTAssertEqual(EvidenceFrameMapper.select(r, count: Int(k)!), sel, "\(tag) select k=\(k)")
                }
                let cov = EvidenceFrameMapper.coverage(
                    sampledFrameMs: c.sampled_frame_ms, selected: EvidenceFrameMapper.select(r, count: r.budget),
                    events: ev, visual: vi, narrative: na)
                XCTAssertEqual([cov.eventsCovered, cov.eventsTotal], exp.coverage["events"], "\(tag) event coverage")
                XCTAssertEqual([cov.visualCovered, cov.visualTotal], exp.coverage["visual"], "\(tag) visual coverage")
                XCTAssertEqual([cov.narrativeCovered, cov.narrativeTotal], exp.coverage["narrative"],
                               "\(tag) narrative coverage")
            }
        }
    }

    // RankedFrames (what the device actually holds) must select exactly what the index ranking selects.
    func test_ranked_frames_select_the_same_timestamps_as_the_index_ranking() throws {
        let f = try loadFixture()
        for c in f.cases {
            let frames = c.sampled_frame_ms.map { AUExtractedFrame(jpeg: Data([1]), tMs: $0) }
            for vt in [EvidenceVideoType.highlights, .fullStory] {
                let g = EditorialFrameGuidance(videoType: vt, visual: cands(c.visual), narrative: cands(c.narrative),
                                               events: cands(c.events))
                let rf = EvidenceFrameMapper.rank(frames, guidance: g)
                let r = EvidenceFrameMapper.rank(videoType: vt, sampledFrameMs: c.sampled_frame_ms,
                                                 events: g.events, visual: g.visual, narrative: g.narrative)
                XCTAssertEqual(rf.preferred, r.budget, c.name)
                for k in [3, r.budget, EvidenceFrameMapper.maxFrames] {
                    XCTAssertEqual(rf.frames(count: k).map { $0.tMs },
                                   EvidenceFrameMapper.select(r, count: k).map { c.sampled_frame_ms[$0] },
                                   "\(c.name) k=\(k)")
                }
            }
        }
    }
}
